selection_gap={'excluded_source_records':len(excluded),'needs_clarification':sum(bool(r['expected'].get('needs_clarification')) for r in excluded),'legacy_missing_items':sum(bool(r['expected'].get('missing_information')) for r in excluded),'expected_paths':dict(collections.Counter(r['expected']['execution_path'] for r in excluded)),'reason':'Review population is filtered by consolidation failures; this is not a random sample of source v4.'}
